package org.apache.commons.math.distribution;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.exception.NotStrictlyPositiveException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.special.Erf;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math3.exception.MathException;
import org.apache.commons.math3.util.FastMath;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for NormalDistributionImpl#cumulativeProbability.
 */
public class NormalDistributionImpl_cumulativeProbability_TriageGen2Test {

    private static final double DELTA = 1e-9;

    @Test
    public void testCumulativeProbability_ExtremeNegative() throws MathException {
        double mean = 0.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);

        // dev = -41.0, which is < -40 * 1.0
        double x = -41.0;
        double result = dist.cumulativeProbability(x);

        Assert.assertEquals(0.0d, result, DELTA);
    }

    @Test
    public void testCumulativeProbability_ExtremePositive() throws MathException {
        double mean = 0.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);

        // dev = 41.0, which is > 40 * 1.0
        double x = 41.0;
        double result = dist.cumulativeProbability(x);

        Assert.assertEquals(1.0d, result, DELTA);
    }

    @Test
    public void testCumulativeProbability_AtMean() throws MathException {
        double mean = 10.0;
        double sd = 2.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);

        // dev = 0.0, 0.0 is not > 40 * 2.0
        // result = 0.5 * (1.0 + erf(0)) = 0.5
        double x = 10.0;
        double result = dist.cumulativeProbability(x);

        Assert.assertEquals(0.5d, result, DELTA);
    }

    @Test
    public void testCumulativeProbability_StandardNormalValue() throws MathException {
        double mean = 0.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);

        // Testing x = 1.0 (approx 0.8413447)
        // Note: The implementation uses a modulo operator in the erf argument:
        // (dev) % (standardDeviation * FastMath.sqrt(2.0))
        // For x=1, dev=1, denom=1.414... -> 1 % 1.414 = 1.0
        double x = 1.0;
        double expected = 0.5 * (1.0 + org.apache.commons.math3.special.Erf.erf(1.0 / FastMath.sqrt(2.0)));
        // Wait, the provided code has: Erf.erf((dev) % (standardDeviation * FastMath.sqrt(2.0)))
        // This looks like a potential bug in the target source (missing division by sqrt(2)), 
        // but I must test the code AS PROVIDED.

        double dev = x - mean;
        double expectedProvidedCode = 0.5 * (1.0 + org.apache.commons.math3.special.Erf.erf(dev % (sd * FastMath.sqrt(2.0))));

        double result = dist.cumulativeProbability(x);
        Assert.assertEquals(expectedProvidedCode, result, DELTA);
    }

    @Test
    public void testCumulativeProbability_ModuloEdgeCase() throws MathException {
        double mean = 0.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);

        // Test a value where dev is exactly the modulo divisor
        // dev = sqrt(2), sd * sqrt(2) = sqrt(2). dev % divisor = 0
        double x = FastMath.sqrt(2.0);
        double result = dist.cumulativeProbability(x);

        // If dev % divisor == 0, result = 0.5 * (1 + erf(0)) = 0.5
        Assert.assertEquals(0.5d, result, DELTA);
    }

    @Test
    public void testCumulativeProbability_BoundaryNear40SD() throws MathException {
        double mean = 0.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);

        // Just inside the 40 limit
        double xInside = 39.9 * sd;
        double resultInside = dist.cumulativeProbability(xInside);
        Assert.assertTrue(resultInside > 0.0 && resultInside < 1.0);

        // Just outside the 40 limit
        double xOutside = 40.1 * sd;
        double resultOutside = dist.cumulativeProbability(xOutside);
        Assert.assertEquals(1.0d, resultOutside, DELTA);
    }
}
